/**
* Benchmark `tinymt32`.
*/
#include "stdlib/random/base/tinymt32.h"
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <math.h>
#include <sys/time.h>

#define NAME "tinymt32"
#define ITERATIONS 1000000
#define REPEATS 3

// TinyMT32 constants
#define MAT1 0x8F7011EE
#define MAT2 0xFC78FF1F
#define TMAT 0x3793FDFF

/**
* Prints the TAP version.
*/
void print_version() {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total ); // TAP plan
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Returns a timestamp with microsecond precision.
*
* @return current time in microseconds
*/
double tic() {
	struct timeval t;
	int ret = gettimeofday( &t, NULL );
	if ( ret != 0 ) {
		fprintf( stderr, "Error: Failed to get time.\n" );
		exit( 1 );
	}
	return (double)t.tv_sec + (double)t.tv_usec*1.0e-6;
}

/**
* Generates a random unsigned 32-bit integer.
*
* @param state    pointer to state array
* @return random unsigned 32-bit integer
*/
uint32_t next( uint32_t *state ) {
	uint32_t y;
	uint32_t x;

	// Mix state
	y = state[3];
	x = (state[0] & 0x7FFFFFFF) ^ state[1] ^ state[2];
	x ^= (x << 1);
	y ^= (y >> 1) ^ x;
	state[0] = state[1];
	state[1] = state[2];
	state[2] = x ^ (y << 10);
	state[3] = y;

	// Tempering
	if (y & 1) {
		state[1] ^= MAT1;
		state[2] ^= MAT2;
	}

	y = state[0] + (state[2] >> 8);
	return (y ^ TMAT);
}

/**
* Returns a normalized pseudorandom number on the interval [0,1).
*
* @return double normalized pseudorandom number
*/
double tinymt32_normalized( uint32_t *state ) {
	return (double)next( state ) / (double)(UINT32_MAX + 1);
}

/**
* Runs a benchmark.
*
* @return elapsed time in seconds
*/
double benchmark() {
	double elapsed;
	double t;
	uint32_t state[4];
	uint32_t v;
	int i;

	// Initialize state
	state[0] = 12345;
	state[1] = MAT1;
	state[2] = MAT2;
	state[3] = TMAT;

	t = tic();
	for ( i = 0; i < ITERATIONS; i++ ) {
		v = tinymt32_normalized( state );
		if ( v < 0.0 || v >= 1.0 ) {
			printf( "unexpected value: %f\n", v );
			exit( 1 );
		}
	}
	elapsed = tic() - t;
	if ( v < 0.0 || v >= 1.0 ) {
		printf( "Warning: Unexpected value: %f\n", v );
	}
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int i;

	print_version();

	for ( i = 0; i < REPEATS; i++ ) {
		printf( "# c::%s\n", NAME );
		elapsed = benchmark();
		printf( "ok %d benchmark finished in %0.9fs\n", i+1, elapsed );
	}
	print_summary( REPEATS, REPEATS );

	return 0;
}